package byblos

// Orientation metadata (owner decision 2026-11-09, docs/guides/orientation.md):
// well-formed files get img2pdf's rotation (testdata/img2pdf/r4, 32 files);
// ambiguous ones get 0 and Ambiguous; defects img2pdf refuses are errors
// (testdata/img2pdf/r5, generated by r5/gen.py, with img2pdf's own result in
// its oracle.json).

import (
	"encoding/json"
	"os"
	"strings"
	"testing"
)

func orientationOracle(t *testing.T, dir string) map[string]img2pdfEntry {
	t.Helper()
	raw, err := os.ReadFile("testdata/img2pdf/" + dir + "/oracle.json")
	if err != nil {
		t.Fatal(err)
	}
	var m map[string]img2pdfEntry
	if err := json.Unmarshal(raw, &m); err != nil {
		t.Fatal(err)
	}
	return m
}

// orientationOf is what a caller learns from a file: EXIFOrientation, and
// the Embed function's own refusal if it has one.
func orientationOf(t *testing.T, name string, data []byte) (Orientation, error) {
	t.Helper()
	o, err := EXIFOrientation(data, Limits{})
	switch {
	case err != nil || strings.HasPrefix(name, "rgba-"): // EmbedPNG refuses alpha
	case strings.HasSuffix(name, ".png"):
		_, _, err = EmbedPNG(data)
	default:
		_, _, err = EmbedJPEG(data)
	}
	return o, err
}

func TestOrientationRound4MatchesImg2pdf(t *testing.T) {
	for name, want := range orientationOracle(t, "r4") {
		data, err := os.ReadFile("testdata/img2pdf/r4/" + name)
		if err != nil {
			t.Fatal(err)
		}
		o, err := orientationOf(t, name, data)
		switch {
		case strings.HasPrefix(name, "rgba-") && want.Error != "" && !strings.Contains(want.Error, "TIFF"):
			// pHYs, page size: EmbedPNG's and BuildPDF's refusals, tested on the grey twin
		case strings.Contains(name, "aspect-big"): // BuildPDF's page size refusal, not orientation
		case want.Error != "":
			if err == nil {
				t.Errorf("%s: got %+v; img2pdf refuses (%s)", name, o, want.Error)
			}
		case name == "png-exif-afteridat6.png" || name == "rgba-png-exif-afteridat6.png":
			// img2pdf reads an eXIf after the IDAT; the rule does not.
			if err != nil || o != (Orientation{Ambiguous: true}) {
				t.Errorf("%s: got %+v, %v; want ambiguous", name, o, err)
			}
		case err != nil || o.Rotate != want.Rotate || o.Ambiguous:
			t.Errorf("%s: got %+v, %v; img2pdf wrote /Rotate %d", name, o, err, want.Rotate)
		}
	}
}

// ambiguous: rotation 0 and Ambiguous. Every other r5 entry img2pdf accepts
// is well formed and keeps img2pdf's rotation; the rest are parked.
var r5Ambiguous = map[string]bool{
	"pre-exif6-post-exif1.png": true, "pre-exif1-post-exif6.png": true,
	"pre-exifnoor-post-xmp6.png": true, "pre-exifnoor-post-text-exif6.png": true,
	"xmp6-then-text-empty.png": true, "text-xmp-noor-then-itxt-badutf8-6.png": true,
	"xmp6-then-itxt-corrupt-zlib.png": true, "itxt-rawprof-badlang6.png": true,
	"post-badtype-then-exif6.png": true, "post-exif6-badcrc.png": true,
}

func TestOrientationRound5(t *testing.T) {
	for name, want := range orientationOracle(t, "r5") {
		data, err := os.ReadFile("testdata/img2pdf/r5/" + name)
		if err != nil {
			t.Fatal(err)
		}
		o, err := orientationOf(t, name, data)
		base := strings.TrimPrefix(name, "rgba-")
		switch {
		case want.Error != "":
			if err == nil {
				t.Errorf("%s: got %+v; img2pdf refuses (%s)", name, o, want.Error)
			}
		case r5Ambiguous[base]:
			if err != nil || o != (Orientation{Ambiguous: true}) {
				t.Errorf("%s: got %+v, %v; want rotation 0 and ambiguous", name, o, err)
			}
		case err != nil || o.Rotate != want.Rotate || o.Ambiguous:
			t.Errorf("%s: got %+v, %v; img2pdf wrote /Rotate %d", name, o, err, want.Rotate)
		}
	}
}

// 70 zTXt chunks of 1 MB (a key nobody reads) are 70 MB of text: img2pdf
// refuses past 64 MiB, so does EXIFOrientation.
func TestOrientationTextOverBudgetParks(t *testing.T) {
	var chunks [][]byte
	for k := 0; k < 70; k++ {
		chunks = append(chunks, pngTextChunk("zTXt", "C"+string(rune('A'+k%26))+string(rune('a'+k/26)), make([]byte, 1000000)))
	}
	if _, err := EXIFOrientation(pngBeforeIDAT(t, chunks...), Limits{}); limitNamed(err) != "png-text-bytes" {
		t.Errorf("err = %v; want *LimitError png-text-bytes", err)
	}
}
